// Run with Node.js 24+. The password is read from hidden terminal input, never a command argument.
import {pbkdf2Sync,createDecipheriv,createHash} from 'node:crypto';
import {readFile,mkdir,writeFile,stat,rm,open,chmod} from 'node:fs/promises';
import {resolve,join,basename} from 'node:path';
import {DatabaseSync} from 'node:sqlite';
import readline from 'node:readline';
const TABLES=['profiles','topics','replies','attachments','subscriptions','notices','cases','audit','limits','intake','intake_files','intake_events','archive_records','archive_media'];
const [manifestArg,partsArg,destinationArg,schemaArg]=process.argv.slice(2);
if(!manifestArg||!partsArg||!destinationArg||!schemaArg){console.log('用法：node restore-private.mjs 加密数据库包 原件分卷目录 新的恢复目录 schema.sql');process.exit(1)}
const destination=resolve(destinationArg);try{await stat(destination);throw Error('恢复目录已存在，拒绝覆盖。')}catch(e){if(e.code!=='ENOENT')throw e}
process.stdout.write('备份密码（隐藏输入）：');let password;
if(process.stdin.isTTY){process.stdin.setRawMode(true);password=await new Promise((resolve,reject)=>{let value='';function onData(b){for(const c of b.toString()){if(c==='\r'||c==='\n'){process.stdin.off('data',onData);process.stdin.setRawMode(false);process.stdin.pause();process.stdout.write('\n');resolve(value);return}if(c==='\u0003'){reject(Error('已取消'));return}if(c==='\u007f')value=value.slice(0,-1);else value+=c}}process.stdin.on('data',onData);process.stdin.resume()})}else{const rl=readline.createInterface({input:process.stdin});password=await new Promise(resolve=>rl.once('line',value=>{rl.close();resolve(value)}))}
function decrypt(raw){const e=JSON.parse(raw);if(e.format!=='jiewangyin-private-encrypted-v1'||e.iterations!==210000)throw Error('备份格式不正确。');const salt=Buffer.from(e.salt,'base64'),iv=Buffer.from(e.iv,'base64'),bytes=Buffer.from(e.ciphertext,'base64');if(salt.length!==16||iv.length!==12||bytes.length<16)throw Error('加密参数不正确。');const key=pbkdf2Sync(password,salt,210000,32,'sha256'),d=createDecipheriv('aes-256-gcm',key,iv);d.setAuthTag(bytes.subarray(-16));return JSON.parse(Buffer.concat([d.update(bytes.subarray(0,-16)),d.final()]).toString('utf8'))}
const snapshot=decrypt(await readFile(resolve(manifestArg),'utf8'));
if(snapshot.format!=='kanjian-private-backup-v1'||!snapshot.tables||!Array.isArray(snapshot.media)||Object.keys(snapshot.tables).some(x=>!TABLES.includes(x))||TABLES.some(x=>!Array.isArray(snapshot.tables[x])))throw Error('数据库目录缺表或格式不正确。');
// Verify ALL files before creating a recovery database.
const files=[];
for(const media of snapshot.media){if(!['community','intake'].includes(media.kind)||!/^[-\w]{8,64}$/.test(media.id)||media.storageKey!==media.kind+'/'+media.id)throw Error('原件存储键不正确。');let offset=0;const hash=createHash('sha256');for(const part of media.parts){if(basename(part.name)!==part.name||part.offset!==offset)throw Error('分卷顺序或名称不正确。');const p=decrypt(await readFile(join(resolve(partsArg),part.name),'utf8'));const bytes=Buffer.from(p.data,'base64');if(p.format!=='kanjian-private-media-part-v1'||p.id!==media.id||p.kind!==media.kind||p.offset!==offset||p.size!==part.size||bytes.length!==part.size||createHash('sha256').update(bytes).digest('hex')!==p.sha256)throw Error('分卷校验失败：'+part.name);offset+=bytes.length;hash.update(bytes);}if(offset!==media.size)throw Error('原件大小不完整：'+media.id);const sha=hash.digest('hex');if(media.sha256&&sha!==media.sha256)throw Error('原件SHA256不一致：'+media.id);files.push({key:media.storageKey,size:offset,sha256:sha,parts:media.parts});}
await mkdir(destination,{mode:0o700});let db;
try{db=new DatabaseSync(join(destination,'community.sqlite3'));db.exec(await readFile(resolve(schemaArg),'utf8'));db.exec('PRAGMA foreign_keys=ON;BEGIN');for(const table of TABLES){const columns=new Set(db.prepare('PRAGMA table_info('+table+')').all().map(x=>x.name));for(const row of snapshot.tables[table]){const keys=Object.keys(row);if(keys.some(k=>!columns.has(k))||keys.length!==columns.size)throw Error('表字段与备份不一致：'+table);db.prepare('INSERT INTO '+table+' ('+keys.map(k=>'"'+k+'"').join(',')+') VALUES ('+keys.map(()=>'?').join(',')+')').run(...keys.map(k=>row[k]))}}if(db.prepare('PRAGMA foreign_key_check').all().length)throw Error('数据库引用不完整。');db.exec('COMMIT');if(db.prepare('PRAGMA integrity_check').get().integrity_check!=='ok')throw Error('数据库完整性检查失败。');db.close();db=null;await mkdir(join(destination,'media'),{mode:0o700});for(const f of files){const output=await open(join(destination,'media',f.key.replaceAll('/','_')),'wx',0o600);const verify=createHash('sha256');let total=0;try{for(const part of f.parts){const p=decrypt(await readFile(join(resolve(partsArg),part.name),'utf8')),bytes=Buffer.from(p.data,'base64');if(createHash('sha256').update(bytes).digest('hex')!==p.sha256)throw Error('分卷在恢复期间变化。');verify.update(bytes);total+=bytes.length;await output.writeFile(bytes);}if(total!==f.size||verify.digest('hex')!==f.sha256)throw Error('恢复原件校验失败。');}finally{await output.close();}}await chmod(join(destination,'community.sqlite3'),0o600);await writeFile(join(destination,'恢复验收.json'),JSON.stringify({format:'jiewangyin-recovery-check-v1',tables:TABLES.map(name=>({name,rows:snapshot.tables[name].length})),files:files.map(f=>({key:f.key,size:f.size,sha256:f.sha256})),note:'本地恢复副本，不是已完成线上灾备切换。'},null,2),{mode:0o600});console.log('已恢复并验证到新的本地目录。未覆盖线上数据库。');}catch(e){db?.close();await rm(destination,{recursive:true,force:true});throw e}
